?>
<section class="requests-header"><div><span>Control interno de almacén</span><h3>Solicitudes de uniformes escolares</h3><p>Las solicitudes se vinculan automáticamente al Servicio Regional oficial de cada escuela.</p></div><div class="requests-header-metrics"><div><strong><?= numero($totalSolicitudes) ?></strong><span>Solicitudes</span></div><div><strong><?= numero($totalUniformes) ?></strong><span>Uniformes</span></div><div><strong><?= numero($pendientes) ?></strong><span>Pendientes</span></div></div></section>
<div class="request-actions"><a class="button secondary" href="<?= escapar(url('escuelas')) ?>"><span>⌕</span> Consultar escuelas</a><a class="button" href="<?= escapar(url('solicitud-nueva')) ?>"><span>＋</span> Nueva solicitud</a></div>
<section class="requests-list"><div class="requests-list-heading"><div><span>Registro de solicitudes</span><h3><?= numero($totalSolicitudes) ?> solicitudes registradas</h3></div></div><?php if(!$solicitudes): ?><div class="empty">Aún no hay solicitudes registradas. Cree una solicitud seleccionando primero una escuela.</div><?php endif; ?><?php foreach($solicitudes as $solicitud): ?><article class="request-list-card"><div class="request-list-folio"><span>Folio</span><strong><?= escapar($solicitud['folio']) ?></strong><small><?= escapar($solicitud['fecha_solicitud']) ?></small></div><div class="request-list-school"><span class="request-cct"><?= escapar($solicitud['cct']) ?></span><h4><?= escapar($solicitud['escuela']) ?></h4><p><?= escapar($solicitud['municipio']??'') ?> · <?= escapar($solicitud['localidad']??'') ?></p></div><div class="request-list-regional"><span>Servicio Regional</span><strong><?= escapar($solicitud['servicio_regional']) ?></strong></div><div class="request-list-total"><span>Solicitado</span><strong><?= numero($solicitud['total']) ?></strong><small>uniformes</small></div><div class="request-list-status"><span class="status"><?= escapar(str_replace('_',' ',$solicitud['estado'])) ?></span><?php if(in_array($solicitud['estado'],['PENDIENTE','EN_REVISION','ASIGNADA','EN_PREPARACION'],true)): ?><a class="send-request-button" href="<?= escapar(url('entrega-nueva',['servicio_id'=>$solicitud['servicio_regional_id']])) ?>">Registrar envío →</a><a class="request-detail-link" href="<?= escapar(url('solicitud-editar',['id'=>$solicitud['id']])) ?>">Editar</a><?php endif; ?><a class="request-detail-link" href="<?= escapar(url('solicitud-detalle',['id'=>$solicitud['id']])) ?>">Ver detalle</a></div></article><?php endforeach; ?></section>
